-- System error log table for tracking edge function errors in admin panel
CREATE TABLE IF NOT EXISTS public.system_error_logs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  function_name text NOT NULL,
  error_type text NOT NULL,
  severity text NOT NULL DEFAULT 'warning',
  user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  job_id uuid REFERENCES public.jobs(id) ON DELETE SET NULL,
  resume_id uuid REFERENCES public.resumes(id) ON DELETE SET NULL,
  error_message text NOT NULL,
  error_stack text,
  context_json jsonb DEFAULT '{}'::jsonb,
  is_resolved boolean DEFAULT false,
  resolved_at timestamp with time zone,
  resolution_notes text
);

CREATE INDEX IF NOT EXISTS idx_system_errors_created_at ON public.system_error_logs (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_system_errors_function ON public.system_error_logs (function_name);
CREATE INDEX IF NOT EXISTS idx_system_errors_severity ON public.system_error_logs (severity);
CREATE INDEX IF NOT EXISTS idx_system_errors_unresolved ON public.system_error_logs (is_resolved, created_at DESC);

ALTER TABLE public.system_error_logs ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Admin reads system errors"
  ON public.system_error_logs FOR SELECT TO authenticated
  USING (has_role(auth.uid(), 'admin'::app_role));

CREATE POLICY "Admin updates system errors"
  ON public.system_error_logs FOR UPDATE TO authenticated
  USING (has_role(auth.uid(), 'admin'::app_role));

CREATE POLICY "Service inserts system errors"
  ON public.system_error_logs FOR INSERT
  WITH CHECK (true);

