// Shared error logging helper for Edge Functions
// Import: import { logSystemError } from "../_shared/logError.ts";

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

interface ErrorLogEntry {
  function_name: string;
  error_type: string;
  severity: "critical" | "warning" | "info";
  error_message: string;
  error_stack?: string;
  user_id?: string | null;
  job_id?: string | null;
  resume_id?: string | null;
  context_json?: Record<string, any>;
}

export async function logSystemError(entry: ErrorLogEntry): Promise<void> {
  try {
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );
    await supabase.from("system_error_logs").insert({
      function_name: entry.function_name,
      error_type: entry.error_type,
      severity: entry.severity,
      error_message: entry.error_message.slice(0, 2000),
      error_stack: entry.error_stack?.slice(0, 4000) || null,
      user_id: entry.user_id || null,
      job_id: entry.job_id || null,
      resume_id: entry.resume_id || null,
      context_json: entry.context_json || {},
    });
  } catch {
    // Never throw from error logging — avoid infinite loops
    console.error("[logSystemError] Failed to write error log:", entry.error_message);
  }
}

export function errorToMessage(err: unknown): string {
  if (err instanceof Error) return err.message;
  return String(err);
}

export function errorToStack(err: unknown): string | undefined {
  if (err instanceof Error) return err.stack;
  return undefined;
}
